/**
 * ============================================================================
 * LEAD IMPORT
 * ============================================================================
 * Realtors arrive with leads already somewhere — a spreadsheet, a Zillow
 * export, Follow Up Boss, kvCORE, a CSV a previous brokerage handed them.
 * Asking them to retype 200 rows is how a trial ends on day one.
 *
 * The hard part isn't parsing CSV, it's that every source uses different
 * column names for the same thing. "Email", "Email Address", "E-mail",
 * "PrimaryEmail", "Contact Email" are all the same field. So this guesses the
 * mapping, shows it, and lets the realtor correct it before anything is saved.
 * ============================================================================
 */

export interface ColumnGuess {
  column: string
  field: string | null
  confidence: 'high' | 'low' | 'none'
  sample: string
}

/** Our fields, and the headers each is commonly called in the wild. */
const FIELD_ALIASES: Record<string, string[]> = {
  name: ['name', 'full name', 'fullname', 'contact', 'contact name', 'lead name', 'client'],
  first_name: ['first name', 'firstname', 'first', 'given name'],
  last_name: ['last name', 'lastname', 'last', 'surname', 'family name'],
  email: ['email', 'email address', 'e-mail', 'emailaddress', 'primary email', 'contact email'],
  phone: ['phone', 'phone number', 'mobile', 'cell', 'cell phone', 'telephone', 'primary phone', 'mobile phone'],
  buy_sell_both: ['type', 'lead type', 'buyer/seller', 'buyer or seller', 'intent', 'looking to', 'transaction type'],
  budget: ['budget', 'price', 'price range', 'max price', 'price point', 'target price'],
  address: ['address', 'street', 'property address', 'street address', 'location'],
  city: ['city', 'town'],
  notes: ['notes', 'note', 'comments', 'remarks', 'description', 'details'],
  source: ['source', 'lead source', 'origin', 'came from', 'referral source'],
  date: ['date', 'created', 'created at', 'date added', 'lead date', 'inquiry date']
}

const norm = (s: string) => String(s || '').trim().toLowerCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ')

/**
 * Guess which of our fields each column is.
 *
 * Exact alias match is 'high'; a containment match is 'low' and gets flagged
 * for the user to confirm. Guessing silently is how 200 phone numbers end up
 * in the notes field.
 */
export function guessColumns(headers: string[], firstRow: string[] = []): ColumnGuess[] {
  const used = new Set<string>()

  return headers.map((h, i) => {
    const n = norm(h)
    const sample = firstRow[i] ?? ''

    for (const [field, aliases] of Object.entries(FIELD_ALIASES)) {
      if (used.has(field)) continue
      if (aliases.includes(n)) { used.add(field); return { column: h, field, confidence: 'high' as const, sample } }
    }
    for (const [field, aliases] of Object.entries(FIELD_ALIASES)) {
      if (used.has(field)) continue
      if (aliases.some((a) => n.includes(a) || a.includes(n))) {
        used.add(field)
        return { column: h, field, confidence: 'low' as const, sample }
      }
    }
    return { column: h, field: null, confidence: 'none' as const, sample }
  })
}

/**
 * CSV parser that handles quoted fields containing commas and newlines.
 * A naive split(',') mangles any address, which is most of the file.
 */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = []
  let row: string[] = []
  let cell = ''
  let inQuotes = false

  const src = text.replace(/^\uFEFF/, '')   // strip BOM — Excel adds one

  for (let i = 0; i < src.length; i++) {
    const c = src[i]!
    const next = src[i + 1]

    if (inQuotes) {
      if (c === '"' && next === '"') { cell += '"'; i++ }
      else if (c === '"') inQuotes = false
      else cell += c
    } else if (c === '"') {
      inQuotes = true
    } else if (c === ',') {
      row.push(cell); cell = ''
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && next === '\n') i++
      row.push(cell); cell = ''
      if (row.some((v) => v.trim())) rows.push(row)
      row = []
    } else {
      cell += c
    }
  }
  row.push(cell)
  if (row.some((v) => v.trim())) rows.push(row)

  return rows
}

const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/

export interface MappedLead {
  name?: string
  email?: string
  phone?: string
  buy_sell_both?: string
  budget?: number
  address?: string
  notes?: string
  source?: string
}

export interface ImportResult {
  ready: MappedLead[]
  skipped: { row: number; reason: string }[]
  duplicatesInFile: number
}

/** Normalise whatever the source called it into what we store. */
function normaliseIntent(v: string): string {
  const s = norm(v)
  if (!s) return ''

  const buys = /buy|buyer|purchas/.test(s)
  const sells = /sell|seller|listing|list/.test(s)

  // Check BOTH before either — "buyer/seller" and "buy and sell" mean both,
  // and testing for 'sell' first silently mislabels every one of them.
  if (s.includes('both') || (buys && sells)) return 'both'
  if (sells) return 'sell'
  if (buys) return 'buy'
  return ''
}

function parseBudget(v: string): number | undefined {
  const digits = String(v || '').replace(/[^0-9.]/g, '')
  if (!digits) return undefined
  const n = Number(digits)
  if (!Number.isFinite(n) || n <= 0) return undefined
  // "425" almost certainly means 425k, not $425.
  return n < 10000 ? Math.round(n * 1000) : Math.round(n)
}

/**
 * Turn rows into leads, reporting exactly what was skipped and why.
 *
 * A silent import that drops 40 rows is worse than one that refuses — the
 * realtor believes they have their whole database and only finds out months
 * later when someone was never called.
 */
export function mapRows(
  rows: string[][],
  mapping: Record<number, string | null>
): ImportResult {
  const [, ...body] = rows
  const ready: MappedLead[] = []
  const skipped: { row: number; reason: string }[] = []
  const seenEmails = new Set<string>()
  let duplicatesInFile = 0

  body.forEach((cells, idx) => {
    const rowNo = idx + 2   // 1-indexed, plus the header
    const lead: MappedLead = {}
    let first = '', last = ''

    Object.entries(mapping).forEach(([colIdx, field]) => {
      if (!field) return
      const raw = (cells[Number(colIdx)] ?? '').trim()
      if (!raw) return

      switch (field) {
        case 'first_name': first = raw; break
        case 'last_name': last = raw; break
        case 'name': lead.name = raw; break
        case 'email': lead.email = raw.toLowerCase(); break
        case 'phone': lead.phone = raw; break
        case 'buy_sell_both': lead.buy_sell_both = normaliseIntent(raw); break
        case 'budget': lead.budget = parseBudget(raw); break
        case 'address': case 'city':
          lead.address = lead.address ? `${lead.address}, ${raw}` : raw; break
        case 'notes':
          lead.notes = lead.notes ? `${lead.notes}\n${raw}` : raw; break
        case 'source': lead.source = raw; break
      }
    })

    if (!lead.name && (first || last)) lead.name = [first, last].filter(Boolean).join(' ')

    // An email is what makes a lead contactable, and the server requires it.
    if (!lead.email) { skipped.push({ row: rowNo, reason: 'no email address' }); return }
    if (!EMAIL_RE.test(lead.email)) { skipped.push({ row: rowNo, reason: `email doesn't look valid (${lead.email})` }); return }

    if (seenEmails.has(lead.email)) { duplicatesInFile++; return }
    seenEmails.add(lead.email)

    if (!lead.name) lead.name = lead.email.split('@')[0]
    ready.push(lead)
  })

  return { ready, skipped, duplicatesInFile }
}
<script setup lang="ts">
definePageMeta({ layout: 'authenticated' })
useHead({ title: 'GhostForm | Import leads' })

/**
 * Three steps: choose a file, confirm the column mapping, review what will
 * happen. The confirmation step is the important one — a silent import that
 * drops 40 rows is worse than one that refuses, because the realtor believes
 * they have their whole database and finds out months later.
 */
import { parseCsv, guessColumns, mapRows } from '~/utils/leadImport'

const toast = useToast()
const fileInput = ref<HTMLInputElement | null>(null)
const step = ref<'file' | 'map' | 'done'>('file')
const importing = ref(false)

const rows = ref<string[][]>([])
const guesses = ref<any[]>([])
const mapping = ref<Record<number, string | null>>({})
const onDuplicate = ref<'skip' | 'update'>('skip')
const result = ref<any>(null)

const FIELDS = [
  { value: null, label: "Don't import" },
  { value: 'name', label: 'Full name' },
  { value: 'first_name', label: 'First name' },
  { value: 'last_name', label: 'Last name' },
  { value: 'email', label: 'Email' },
  { value: 'phone', label: 'Phone' },
  { value: 'buy_sell_both', label: 'Buying or selling' },
  { value: 'budget', label: 'Budget' },
  { value: 'address', label: 'Address' },
  { value: 'notes', label: 'Notes' },
  { value: 'source', label: 'Where they came from' }
]

const preview = computed(() => {
  if (!rows.value.length) return null
  return mapRows(rows.value, mapping.value)
})

const hasEmail = computed(() => Object.values(mapping.value).includes('email'))

async function onFile(e: Event) {
  const file = (e.target as HTMLInputElement).files?.[0]
  if (!file) return

  try {
    const text = await file.text()
    const parsed = parseCsv(text)
    if (parsed.length < 2) {
      toast.error('That file has no rows under the header.')
      return
    }
    rows.value = parsed
    guesses.value = guessColumns(parsed[0]!, parsed[1])
    const m: Record<number, string | null> = {}
    guesses.value.forEach((g, i) => { m[i] = g.field })
    mapping.value = m
    step.value = 'map'
  } catch (err) {
    toast.error('Could not read that file. Make sure it is a CSV.')
  } finally {
    if (fileInput.value) fileInput.value.value = ''
  }
}

async function runImport() {
  if (!preview.value?.ready.length) return
  importing.value = true
  try {
    result.value = await $fetch('/api/leads/import', {
      method: 'POST',
      body: { leads: preview.value.ready, onDuplicate: onDuplicate.value }
    })
    await refreshNuxtData('leads')
    step.value = 'done'
  } catch (err: any) {
    toast.error(err?.data?.message || 'Import failed. Please try again.')
  } finally {
    importing.value = false
  }
}
</script>

<template>
  <div class="max-w-3xl mx-auto">
    <header class="mb-12 pt-4">
      <NuxtLink to="/dashboard/leads" class="gf-eyebrow inline-block mb-5 hover:text-[#B5563A] transition-colors">
        ← Leads
      </NuxtLink>
      <h1 class="gf-display text-[clamp(30px,4vw,44px)] mb-4">Bring your leads across.</h1>
      <p class="text-[15.5px] text-[#8A847C] leading-relaxed max-w-[52ch]">
        Export a CSV from wherever your leads live now — a spreadsheet, your old
        CRM, Zillow — and we'll match up the columns for you.
      </p>
    </header>

    <!-- 1 · File -->
    <section v-if="step === 'file'">
      <div
        class="border border-dashed border-[#DDD6C9] p-14 text-center cursor-pointer hover:border-[#A9A39A] transition-colors"
        @click="fileInput?.click()"
      >
        <input ref="fileInput" type="file" accept=".csv,text/csv" class="hidden" @change="onFile" />
        <p class="font-display text-[19px] mb-2">Choose a CSV file</p>
        <p class="text-[13.5px] text-[#8A847C]">
          Most tools have an "Export" option that produces one.
        </p>
      </div>

      <div class="mt-8 p-5 bg-[#EFEAE0] border border-[#DDD6C9]">
        <p class="gf-eyebrow mb-2.5">What we need</p>
        <p class="text-[13.5px] text-[#8A847C] leading-relaxed">
          An email address for each lead — that's what makes them contactable,
          and rows without one can't be imported. Everything else is optional
          and can be filled in later.
        </p>
      </div>
    </section>

    <!-- 2 · Mapping -->
    <section v-else-if="step === 'map'">
      <div class="flex items-baseline justify-between mb-6">
        <p class="gf-eyebrow">Check the columns</p>
        <button class="text-[12.5px] text-[#8A847C] hover:text-[#1F1B16]" @click="step = 'file'">
          Choose a different file
        </button>
      </div>
      <p class="text-[14px] text-[#8A847C] leading-relaxed max-w-[54ch] mb-8">
        We've guessed what each column is. Anything marked
        <span class="text-[#B5563A]">check this</span> is a guess worth
        confirming before you import.
      </p>

      <div class="border-t border-[#DDD6C9] mb-8">
        <div
          v-for="(g, i) in guesses" :key="i"
          class="grid gap-4 py-4 border-b border-[#DDD6C9] items-center"
          style="grid-template-columns: 1fr auto"
        >
          <div class="min-w-0">
            <p class="text-[14.5px] font-semibold truncate">{{ g.column }}</p>
            <p class="text-[12.5px] text-[#A9A39A] truncate">
              e.g. {{ g.sample || '(empty)' }}
              <span v-if="g.confidence === 'low'" class="text-[#B5563A]"> · check this</span>
            </p>
          </div>
          <select
            v-model="mapping[i]"
            class="bg-[#F7F4EF] border border-[#DDD6C9] px-3 py-2.5 text-[13.5px] focus:outline-none focus:border-[#B5563A]"
          >
            <option v-for="f in FIELDS" :key="String(f.value)" :value="f.value">{{ f.label }}</option>
          </select>
        </div>
      </div>

      <div v-if="!hasEmail" class="p-4 border-l-2 border-[#B5563A] bg-[#B5563A]/5 mb-8">
        <p class="text-[13.5px]">
          No column is set to Email. Pick one before importing — a lead without
          an email can't be followed up.
        </p>
      </div>

      <div v-else-if="preview" class="mb-8">
        <p class="gf-eyebrow mb-4">What will happen</p>
        <div class="grid sm:grid-cols-3 gap-px bg-[#DDD6C9] border border-[#DDD6C9] mb-5">
          <div class="bg-[#F7F4EF] p-5">
            <p class="font-display text-[30px] leading-none">{{ preview.ready.length }}</p>
            <p class="text-[12.5px] text-[#8A847C] mt-1.5">will be imported</p>
          </div>
          <div class="bg-[#F7F4EF] p-5">
            <p class="font-display text-[30px] leading-none">{{ preview.skipped.length }}</p>
            <p class="text-[12.5px] text-[#8A847C] mt-1.5">skipped</p>
          </div>
          <div class="bg-[#F7F4EF] p-5">
            <p class="font-display text-[30px] leading-none">{{ preview.duplicatesInFile }}</p>
            <p class="text-[12.5px] text-[#8A847C] mt-1.5">duplicates in the file</p>
          </div>
        </div>

        <!-- Named, not just counted. "12 skipped" tells you nothing. -->
        <details v-if="preview.skipped.length" class="mb-5">
          <summary class="text-[13px] text-[#B5563A] cursor-pointer">
            Why {{ preview.skipped.length }} were skipped
          </summary>
          <ul class="mt-3 space-y-1.5">
            <li v-for="s in preview.skipped.slice(0, 25)" :key="s.row" class="text-[12.5px] text-[#8A847C]">
              Row {{ s.row }} — {{ s.reason }}
            </li>
            <li v-if="preview.skipped.length > 25" class="text-[12.5px] text-[#A9A39A]">
              …and {{ preview.skipped.length - 25 }} more
            </li>
          </ul>
        </details>

        <p class="gf-eyebrow mb-3">If a lead is already in your database</p>
        <div class="flex gap-2.5">
          <button
            v-for="opt in [
              { v: 'skip', l: 'Leave it alone', h: 'Keeps what you already have' },
              { v: 'update', l: 'Fill in blanks', h: 'Adds missing details only' }
            ]" :key="opt.v"
            class="flex-1 text-left px-4 py-3 border transition-colors"
            :class="onDuplicate === opt.v ? 'border-[#B5563A] bg-[#B5563A]/5' : 'border-[#DDD6C9]'"
            @click="onDuplicate = opt.v as any"
          >
            <span class="block text-[14px] font-semibold">{{ opt.l }}</span>
            <span class="block text-[12px] text-[#A9A39A] mt-0.5">{{ opt.h }}</span>
          </button>
        </div>
      </div>

      <button
        class="px-7 py-3.5 bg-[#B5563A] text-[#F7F4EF] text-[11px] uppercase tracking-[0.12em] font-semibold hover:bg-[#9d4830] transition-colors disabled:opacity-40"
        :disabled="importing || !hasEmail || !preview?.ready.length"
        @click="runImport"
      >
        {{ importing ? 'Importing…' : `Import ${preview?.ready.length ?? 0} leads` }}
      </button>
    </section>

    <!-- 3 · Done -->
    <section v-else class="border border-[#DDD6C9] p-12 text-center">
      <p class="font-display text-[24px] mb-3">
        {{ result?.inserted }} leads added
      </p>
      <p class="text-[14px] text-[#8A847C] leading-relaxed max-w-[44ch] mx-auto mb-8">
        <template v-if="result?.updated">{{ result.updated }} existing leads were updated. </template>
        They're on your list now and will appear in tomorrow's briefing.
      </p>
      <div class="flex flex-wrap gap-3 justify-center">
        <baseButtonNavigate text="See your leads" path="/dashboard/leads" />
        <button class="px-6 py-3.5 border border-[#DDD6C9] text-[#8A847C] text-[11px] uppercase tracking-[0.12em] font-semibold hover:border-[#1F1B16] hover:text-[#1F1B16]"
          @click="step = 'file'; result = null">
          Import another file
        </button>
      </div>
    </section>
  </div>
</template>
